import hashlib
import json
import time

import boto3
from botocore.exceptions import ClientError

sm = boto3.client('secretsmanager')


def fingerprint(value):
    return hashlib.sha256(value.encode()).hexdigest() if value else None


def emit(kind, **fields):
    print(json.dumps({'probe': 'stackd-sm-rotation', 'kind': kind, 'time_ms': int(time.time() * 1000), **fields}, sort_keys=True), flush=True)


def handler(event, context):
    secret_id = event.get('SecretId')
    token = event.get('ClientRequestToken')
    step = event.get('Step')
    emit('callback_started', secret=secret_id, step=step, token_sha256=fingerprint(token), rotation_token_present=bool(event.get('RotationToken')))
    try:
        rotate(event)
    except Exception as error:
        code = error.response['Error']['Code'] if isinstance(error, ClientError) else type(error).__name__
        emit('callback_failed', secret=secret_id, step=step, token_sha256=fingerprint(token), error_code=code)
        raise RuntimeError('Owned rotation probe failed with ' + code) from None
    emit('callback_succeeded', secret=secret_id, step=step, token_sha256=fingerprint(token))


def rotate(event):
    secret_id = event['SecretId']
    token = event['ClientRequestToken']
    step = event['Step']
    metadata = sm.describe_secret(SecretId=secret_id)
    versions = metadata.get('VersionIdsToStages', {})
    emit('stage_state', secret=secret_id, step=step, rotation_enabled=metadata.get('RotationEnabled', False), versions={fingerprint(k): v for k, v in versions.items()})
    if not metadata.get('RotationEnabled'):
        raise ValueError('Rotation is not enabled')
    if token not in versions:
        raise ValueError('Token is not registered as a secret version')
    if 'AWSCURRENT' in versions[token]:
        emit('already_current', secret=secret_id, step=step)
        return
    if 'AWSPENDING' not in versions[token]:
        raise ValueError('Token does not own AWSPENDING')
    if step == 'createSecret':
        current = sm.get_secret_value(SecretId=secret_id, VersionStage='AWSCURRENT')
        try:
            sm.get_secret_value(SecretId=secret_id, VersionId=token, VersionStage='AWSPENDING')
            emit('pending_already_exists', secret=secret_id, step=step)
            return
        except sm.exceptions.ResourceNotFoundException:
            pass
        payload = json.loads(current['SecretString'])
        if payload.get('probe') != 'inert-stackd-rotation':
            raise ValueError('Unexpected synthetic probe secret')
        payload['generation'] += 1
        args = {'SecretId': secret_id, 'ClientRequestToken': token, 'SecretString': json.dumps(payload, sort_keys=True), 'VersionStages': ['AWSPENDING']}
        if event.get('RotationToken'):
            args['RotationToken'] = event['RotationToken']
        created = sm.put_secret_value(**args)
        emit('pending_created', secret=secret_id, step=step, version_sha256=fingerprint(created['VersionId']), generation=payload['generation'])
    elif step in ('setSecret', 'testSecret'):
        pending = sm.get_secret_value(SecretId=secret_id, VersionId=token, VersionStage='AWSPENDING')
        payload = json.loads(pending['SecretString'])
        if payload.get('probe') != 'inert-stackd-rotation' or not isinstance(payload.get('generation'), int):
            raise ValueError('Invalid inert synthetic credential')
        # This probe has no backing database or third-party credential system.
        # setSecret/testSecret validate the real pending secret instead of mutating any external service.
        emit('pending_validated', secret=secret_id, step=step, generation=payload['generation'])
        if step == 'setSecret' and '-cancel-' in secret_id:
            emit('cancellation_window_open', secret=secret_id, step=step, hold_seconds=25)
            time.sleep(25)
            if not sm.describe_secret(SecretId=secret_id).get('RotationEnabled'):
                emit('cancellation_observed', secret=secret_id, step=step)
                raise ValueError('Rotation canceled during controlled callback pause')
    elif step == 'finishSecret':
        current = next((version for version, stages in versions.items() if 'AWSCURRENT' in stages), None)
        if current == token:
            return
        args = {'SecretId': secret_id, 'VersionStage': 'AWSCURRENT', 'MoveToVersionId': token}
        if current:
            args['RemoveFromVersionId'] = current
        sm.update_secret_version_stage(**args)
        final = sm.describe_secret(SecretId=secret_id)
        emit('current_promoted', secret=secret_id, step=step, versions={fingerprint(k): v for k, v in final.get('VersionIdsToStages', {}).items()})
    else:
        raise ValueError('Unknown rotation step')

