import json
from pathlib import Path

path = Path('/home/r/dev/minor/stackd/testdata/aws/secretsmanager/rotation_replication.json')
fixture = json.loads(path.read_text())
records = fixture['observations'] + fixture['cleanup']
seen = set()
callbacks = []
for record in records:
    if record['service'] != 'logs' or record['operation'] != 'filter-log-events':
        continue
    for event in record['result'].get('output', {}).get('events', []):
        identity = event.get('eventId') or (event['timestamp'], event['message'])
        if identity in seen:
            continue
        seen.add(identity)
        try:
            callback = json.loads(event['message'])
        except ValueError:
            continue
        if callback.get('probe') == 'stackd-sm-rotation':
            callbacks.append({'event_timestamp_ms': event['timestamp'], 'event_id': event.get('eventId'), **callback})
fixture['callback_events_deduplicated'] = sorted(callbacks, key=lambda item: item['event_timestamp_ms'])
fixture['cleanup_evidence_summary'] = {
    'successful_delete_requests': [
        {'label': r['label'], 'service': r['service'], 'operation': r['operation'], 'region': r['region'], 'input': r['input'], 'request_finished_ms': r['request_finished_ms'], 'result': r['result']}
        for r in records
        if r['operation'] in ('delete-secret', 'delete-function', 'delete-log-group', 'delete-role', 'delete-role-policy') and r['result']['code'] == 'Success'
    ],
    'independently_confirmed_absence': [
        {'label': r['label'], 'service': r['service'], 'operation': r['operation'], 'region': r['region'], 'input': r['input'], 'request_finished_ms': r['request_finished_ms'], 'result': r['result']}
        for r in records
        if r['label'].startswith(('confirm-', 'replica-absent-after-removal')) and (
            r['result']['code'] in ('ResourceNotFoundException', 'NoSuchEntity')
            or (r['operation'] == 'describe-log-groups' and r['result'].get('output', {}).get('logGroups') == [])
        )
    ],
    'kms_keys_created': False,
    'scope': 'Only uniquely named owned resources; no shared/default policies were changed.'
}
fixture['references'] = [
    'https://docs.aws.amazon.com/secretsmanager/latest/apireference/API_RotateSecret.html',
    'https://docs.aws.amazon.com/secretsmanager/latest/apireference/API_CancelRotateSecret.html',
    'https://docs.aws.amazon.com/secretsmanager/latest/apireference/API_RemoveRegionsFromReplication.html',
    'https://docs.aws.amazon.com/secretsmanager/latest/userguide/rotate-secrets_lambda-functions.html'
]
fixture['source']['evidence_summary_python'] = Path(__file__).read_text()
path.write_text(json.dumps(fixture, indent=2) + '\n')
print(json.dumps({'probe_completed': fixture.get('probe_completed'), 'observations': len(fixture['observations']), 'cleanup_records': len(fixture['cleanup']), 'callback_events': len(callbacks), 'unresolved': fixture['unresolved'], 'callback_successes': [{'secret': x.get('secret'), 'step': x.get('step'), 'token_sha256': x.get('token_sha256')} for x in callbacks if x.get('kind') == 'callback_succeeded'], 'successful_delete_requests': len(fixture['cleanup_evidence_summary']['successful_delete_requests']), 'absence_confirmations': len(fixture['cleanup_evidence_summary']['independently_confirmed_absence'])}, indent=2))
